const cmds=[
"rg -n '^(noncomputable )?(def|theorem|lemma|instance|class|structure)\\b|Galois|representable' AlgebraicJacobian/Picard/Pic0CriticalPath.lean",
"nl -ba AlgebraicJacobian/Picard/Pic0CriticalPath.lean | sed -n '1,180p'",
"tail -n 180 AlgebraicJacobian/Picard/Pic0CriticalPath.lean | nl -ba",
"rg -n 'Pic0CriticalPath' AlgebraicJacobian.lean"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({
 cmd,
 workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
 yield_time_ms:10000,
 max_output_tokens:30000
})));
rs.forEach((r,i)=>text(`===== ${i+1} =====\n${r.output}`));

const files=[
"AlgebraicJacobian/Picard/Pic0SigmaEtaleSheaf.lean",
"AlgebraicJacobian/Picard/Pic0SigmaEtaleSheafificationComparison.lean",
"AlgebraicJacobian/Picard/Pic0EtaleDegreeZero.lean",
"AlgebraicJacobian/Picard/Pic0AffineEtaleDescent.lean"
];
const rs=await Promise.all(files.map(file=>tools.exec_command({
 cmd:`rg -n '^(noncomputable )?(def|abbrev|theorem|lemma|instance|class|structure)\\b' ${file}`,
 workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
 yield_time_ms:10000,
 max_output_tokens:20000
})));
rs.forEach((r,i)=>text(`===== ${files[i]} =====\n${r.output}`));

const cmds=[
"nl -ba AlgebraicJacobian/Picard/Pic0SigmaEtaleSheaf.lean | sed -n '1,270p'",
"nl -ba AlgebraicJacobian/Picard/Pic0AffineEtaleDescent.lean | sed -n '1,100p'",
"nl -ba AlgebraicJacobian/Picard/Pic0EtaleDegreeZero.lean | sed -n '1,100p'",
"nl -ba AlgebraicJacobian/Picard/Pic0SigmaEtaleSheafificationComparison.lean | sed -n '1,110p'"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({
 cmd,
 workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
 yield_time_ms:10000,
 max_output_tokens:50000
})));
rs.forEach((r,i)=>text(`===== ${i+1} =====\n${r.output}`));

const cmds = [
  ["Orbit-affineness producers", "rg -n 'OrbitsInAffineOpen' AlgebraicJacobian | head -200", 20000],
  ["Quotient existence consumers/producers", "rg -n 'HasGaloisQuotient|gluedQuotientOver|hasGaloisQuotient_of_orbitsInAffineOpen' AlgebraicJacobian | head -200", 20000],
  ["No placeholders in target files", "rg -n '\\bsorry\\b|\\badmit\\b' AlgebraicJacobian/Descent/GaloisQuotientDescent.lean AlgebraicJacobian/Descent/GaloisQuotientOverlap.lean || true", 4000]
];
const results = await Promise.all(cmds.map(async ([label, cmd, max_output_tokens]) => {
  const r = await tools.exec_command({cmd, workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild", yield_time_ms:10000, max_output_tokens});
  return {label, ...r};
}));
for (const r of results) {
  text(`--- ${r.label} ---\n${r.output}\n`);
}

const cmds=[
"rg -n '^(noncomputable )?(def|abbrev|theorem|lemma|instance|class|structure)\\b' AlgebraicJacobian/Descent/GaloisKernelCover.lean",
"nl -ba AlgebraicJacobian/Descent/GaloisKernelCover.lean | sed -n '1,280p'",
"rg -n 'coverSelfSection|coverMap|twistLeft|kernel' AlgebraicJacobian/Descent/GaloisKernelCover.lean"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({
 cmd,
 workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
 yield_time_ms:10000,
 max_output_tokens:50000
})));
rs.forEach((r,i)=>text(`===== ${i+1} =====\n${r.output}`));

const cmds=[
"rg -n 'isSheafFor_singleton|singleton_mem.*etale|etaleTopology.*singleton|singleton_mem_precoverage_iff' AlgebraicJacobian/Picard AlgebraicJacobian/Descent --glob '*.lean'",
"rg -n 'pic0SigmaFunctor_isSheaf_etale|pic0SigmaFunctor_presheafIsSheaf_etale' AlgebraicJacobian --glob '*.lean'",
"rg -n 'Presieve.IsSheafFor.*singleton|isSheafFor.*singleton' .lake/packages/mathlib/Mathlib/AlgebraicGeometry .lake/packages/mathlib/Mathlib/CategoryTheory --glob '*.lean' | head -n 80"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({
 cmd,
 workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
 yield_time_ms:10000,
 max_output_tokens:30000
})));
rs.forEach((r,i)=>text(`===== ${i+1} =====\n${r.output}`));

const cmds = [
  ["FiniteInAffine producer", "nl -ba AlgebraicJacobian/Descent/FiniteInAffine.lean | sed -n '1,90p'", 18000],
  ["Critical-path uses around quotient", "nl -ba AlgebraicJacobian/Picard/Pic0CriticalPath.lean | sed -n '430,525p'", 22000],
  ["Galois quotient glue status docs", "nl -ba AlgebraicJacobian/Descent/GaloisQuotientGlue.lean | sed -n '1,90p'", 18000]
];
const results = await Promise.all(cmds.map(async ([label, cmd, max_output_tokens]) => {
  const r = await tools.exec_command({cmd, workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild", yield_time_ms:10000, max_output_tokens});
  return {label, ...r};
}));
for (const r of results) {
  text(`--- ${r.label} ---\n${r.output}\n`);
}

